  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "vst-product-lifecycle-entry-schema",
  "title": "VST Product Lifecycle KB Entry Schema",
  "description": "JSON schema for all knowledge base entries in the VST Product Lifecycle Playbook",
  "type": "object",
  "required": [
    "id",
    "kb",
    "topic",
    "status",
    "version",
    "title",
    "summary",
    "description",
    "source",
    "concepts",
    "tags",
    "related_topics",
    "difficulty",
    "domain_relevance"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^vst_(technical|sound-design|ui-ux|commercial|reference)_[a-z0-9-]+$",
      "description": "Unique identifier: vst_{kb}_{entry-name}",
      "examples": [
        "vst_technical_smoothedvalue",
        "vst_sound-design_warm-timbre",
        "vst_ui-ux_knob-design"
      ]
    },
    "kb": {
      "type": "string",
      "enum": ["technical", "sound-design", "ui-ux", "commercial", "reference"],
      "description": "Which knowledge base layer this entry belongs to"
    },
    "topic": {
      "type": "string",
      "description": "Topic within the KB layer",
      "examples": ["cpp-audio", "juce-framework", "dsp-algorithms", "synthesis-types", "genre-techniques"]
    },
    "status": {
      "type": "string",
      "enum": ["placeholder", "harvested", "curated", "synced"],
      "description": "Entry lifecycle status"
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Semantic version of this entry",
      "default": "1.0.0"
    },
    "title": {
      "type": "string",
      "description": "Human-readable title",
      "examples": ["SmoothedValue for Parameter Smoothing", "Warm Timbre Translation", "Knob Control Design"]
    },
    "summary": {
      "type": "string",
      "description": "One-line summary (max 100 characters)",
      "maxLength": 100
    },
    "description": {
      "type": "string",
      "description": "Full description with substantive content (min 100 characters)",
      "minLength": 100
    },
    "source": {
      "type": "object",
      "required": ["type", "reference"],
      "properties": {
        "type": {
          "type": "string",
          "enum": ["academic", "textbook", "expert-tutorial", "framework-docs", "standards", "research", "sme-knowledge", "placeholder"],
          "description": "Type of source"
        },
        "reference": {
          "type": "string",
          "description": "Specific reference citation",
          "examples": ["Will Pirkle, Designing Audio Effect Plugins", "JUCE SmoothedValue Documentation", "research/domain-analysis.md:audio-thread-safety"]
        },
        "url": {
          "type": "string",
          "description": "Optional URL for online sources"
        }
      }
    },
    "concepts": {
      "type": "array",
      "description": "Key concepts covered in this entry",
      "minItems": 2,
      "items": {
        "type": "object",
        "required": ["name", "description"],
        "properties": {
          "name": {
            "type": "string",
            "description": "Concept name"
          },
          "description": {
            "type": "string",
            "description": "Brief concept description"
          },
          "related": {
            "type": "array",
            "description": "Related concept names",
            "items": { "type": "string" }
          }
        }
      }
    },
    "code_blocks": {
      "type": "array",
      "description": "Code examples (for technical KB)",
      "items": {
        "type": "object",
        "required": ["language", "code"],
        "properties": {
          "language": {
            "type": "string",
            "description": "Programming language",
            "examples": ["cpp", "cmake", "json"]
          },
          "code": {
            "type": "string",
            "description": "Code block content"
          },
          "preserved": {
            "type": "boolean",
            "description": "Whether to preserve exact formatting",
            "default": true
          },
          "description": {
            "type": "string",
            "description": "What this code demonstrates"
          }
        }
      }
    },
    "tags": {
      "type": "array",
      "description": "Searchable tags",
      "minItems": 3,
      "items": { "type": "string" }
    },
    "related_topics": {
      "type": "array",
      "description": "Other topics within same KB",
      "items": { "type": "string" }
    },
    "cross_references": {
      "type": "array",
      "description": "References to entries in other KB layers",
      "items": {
        "type": "object",
        "properties": {
          "kb": { "type": "string" },
          "entry_id": { "type": "string" },
          "relationship": {
            "type": "string",
            "enum": ["implements", "requires", "relates-to", "contrasts-with"]
          }
        }
      }
    },
    "difficulty": {
      "type": "string",
      "enum": ["beginner", "intermediate", "advanced"],
      "description": "Difficulty level for this content"
    },
    "domain_relevance": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Relevance to VST development (1=peripheral, 10=critical)"
    },
    "created": {
      "type": "string",
      "format": "date-time",
      "description": "Creation timestamp"
    },
    "updated": {
      "type": "string",
      "format": "date-time",
      "description": "Last update timestamp"
    },
    "supersedes": {
      "type": "string",
      "description": "ID of entry this supersedes (for versioning)"
    }
  }
}

