{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "vst-product-lifecycle-bridge-schema",
  "title": "VST Product Lifecycle Bridge Schema",
  "description": "JSON schema for bridge entries that translate subjective sound design vocabulary to technical DSP parameters",
  "type": "object",
  "required": [
    "id",
    "category",
    "descriptor",
    "parameters",
    "confidence",
    "source",
    "why"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^bridge_(timbre|dynamics|space|movement|character)_[a-z0-9-]+$",
      "description": "Unique identifier: bridge_{category}_{descriptor-name}",
      "examples": [
        "bridge_timbre_warm",
        "bridge_dynamics_punchy",
        "bridge_space_wide"
      ]
    },
    "category": {
      "type": "string",
      "enum": ["timbre", "dynamics", "space", "movement", "character"],
      "description": "Translation category"
    },
    "descriptor": {
      "type": "string",
      "description": "Subjective descriptor being translated",
      "examples": ["warm", "bright", "dark", "punchy", "smooth", "wide", "evolving", "analog"]
    },
    "parameters": {
      "type": "array",
      "description": "Technical parameter mappings",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["parameter", "value_range", "typical_default"],
        "properties": {
          "parameter": {
            "type": "string",
            "description": "Technical parameter name",
            "examples": ["filter_cutoff", "filter_resonance", "saturation_amount", "attack_time", "reverb_mix"]
          },
          "value_range": {
            "type": "array",
            "minItems": 2,
            "maxItems": 2,
            "items": { "type": "number" },
            "description": "Valid range [min, max] normalized 0.0-1.0",
            "examples": [[0.2, 0.4], [0.6, 1.0]]
          },
          "typical_default": {
            "type": "number",
            "description": "Typical starting value within range"
          },
          "unit": {
            "type": "string",
            "description": "Unit if applicable",
            "examples": ["Hz", "ms", "dB", "normalized"]
          },
          "notes": {
            "type": "string",
            "description": "Additional context for this parameter"
          }
        }
      }
    },
    "confidence": {
      "type": "number",
      "minimum": 0.0,
      "maximum": 1.0,
      "description": "Confidence level for this translation (0.0=speculative, 1.0=authoritative)"
    },
    "source": {
      "type": "object",
      "required": ["type", "reference"],
      "properties": {
        "type": {
          "type": "string",
          "enum": ["expert-knowledge", "research", "user-feedback", "auto-generated", "textbook"],
          "description": "Source type for this translation"
        },
        "reference": {
          "type": "string",
          "description": "Specific source reference"
        }
      }
    },
    "why": {
      "type": "string",
      "description": "Human-readable rationale for this translation",
      "minLength": 50
    },
    "anti_patterns": {
      "type": "array",
      "description": "What NOT to do — common mistakes",
      "items": {
        "type": "object",
        "properties": {
          "mistake": {
            "type": "string",
            "description": "The anti-pattern to avoid"
          },
          "reason": {
            "type": "string",
            "description": "Why this is problematic"
          }
        }
      }
    },
    "combinations": {
      "type": "array",
      "description": "Compatible descriptors that can be combined",
      "items": {
        "type": "object",
        "properties": {
          "compatible_with": {
            "type": "string",
            "description": "Descriptor ID that combines well"
          },
          "notes": {
            "type": "string",
            "description": "How to combine successfully"
          },
          "confidence_modifier": {
            "type": "number",
            "description": "Adjust confidence when combined (typically negative)"
          }
        }
      }
    },
    "examples": {
      "type": "array",
      "description": "Example use cases",
      "items": {
        "type": "object",
        "properties": {
          "context": {
            "type": "string",
            "description": "Musical context or genre"
          },
          "parameter_values": {
            "type": "object",
            "description": "Example parameter settings"
          },
          "result": {
            "type": "string",
            "description": "Expected sonic result"
          }
        }
      }
    },
    "created": {
      "type": "string",
      "format": "date-time"
    },
    "updated": {
      "type": "string",
      "format": "date-time"
    },
    "supersedes": {
      "type": "string",
      "description": "ID of bridge entry this supersedes"
    }
  }
}

