{
  "id": "bridge_timbre_warm",
  "category": "timbre",
  "descriptor": "warm",
  "parameters": [
    {
      "parameter": "filter_cutoff",
      "value_range": [0.2, 0.4],
      "typical_default": 0.3,
      "unit": "normalized",
      "notes": "Low-pass filter reduces high frequencies for warmth"
    },
    {
      "parameter": "filter_resonance",
      "value_range": [0.1, 0.25],
      "typical_default": 0.15,
      "unit": "normalized",
      "notes": "Subtle resonance adds character without harshness"
    },
    {
      "parameter": "saturation_amount",
      "value_range": [0.1, 0.3],
      "typical_default": 0.2,
      "unit": "normalized",
      "notes": "Even-harmonic saturation adds warmth"
    }
  ],
  "confidence": 0.85,
  "source": {
    "type": "expert-knowledge",
    "reference": "research/sme-interviews.md#sound-design-knowledge"
  },
  "why": "Warm timbre is achieved by reducing high frequencies (low-pass filter), adding subtle even-harmonic saturation, and sometimes introducing slight detune or analog drift. The combination creates the psychoacoustic impression of warmth associated with vintage analog equipment.",
  "anti_patterns": [
    {
      "mistake": "Heavy saturation",
      "reason": "Too much saturation creates harshness, not warmth"
    },
    {
      "mistake": "High filter resonance",
      "reason": "High resonance at low cutoff creates nasal, not warm, tone"
    }
  ],
  "combinations": [
    {
      "compatible_with": "bridge_character_analog",
      "notes": "Analog character enhances warmth through drift and subtle noise",
      "confidence_modifier": 0.1
    }
  ],
  "examples": [
    {
      "context": "Pad sound",
      "parameter_values": {
        "filter_cutoff": 0.3,
        "filter_resonance": 0.15,
        "saturation_amount": 0.2
      },
      "result": "Warm pad with rounded high frequencies"
    }
  ],
  "created": "2026-04-02T21:15:00Z"
}

