{
  "id": "bridge_dynamics_punchy",
  "category": "dynamics",
  "descriptor": "punchy",
  "parameters": [
    {
      "parameter": "attack_time",
      "value_range": [0.001, 0.01],
      "typical_default": 0.005,
      "unit": "seconds",
      "notes": "Fast attack for immediate transient response"
    },
    {
      "parameter": "filter_envelope_amount",
      "value_range": [0.3, 0.6],
      "typical_default": 0.45,
      "unit": "normalized",
      "notes": "Filter envelope opens briefly then closes, creating punch"
    },
    {
      "parameter": "amp_envelope_sustain",
      "value_range": [0.2, 0.5],
      "typical_default": 0.35,
      "unit": "normalized",
      "notes": "Lower sustain allows punch to decay naturally"
    }
  ],
  "confidence": 0.9,
  "source": {
    "type": "expert-knowledge",
    "reference": "research/sme-interviews.md#sound-design-knowledge"
  },
  "why": "Punchy dynamics come from fast attack transients combined with a filter envelope that briefly opens the filter then closes it. The amplitude envelope has a quick decay to lower sustain, allowing the punch to fade while maintaining presence. This mimics the behavior of percussive acoustic instruments.",
  "anti_patterns": [
    {
      "mistake": "Slow attack time",
      "reason": "Slower attack softens the transient, reducing punch"
    },
    {
      "mistake": "High sustain with no filter envelope",
      "reason": "Creates sustained sound without the dynamic punch transient"
    }
  ],
  "combinations": [
    {
      "compatible_with": "bridge_timbre_bright",
      "notes": "Bright timbre with punchy dynamics creates aggressive lead sounds",
      "confidence_modifier": -0.1
    }
  ],
  "examples": [
    {
      "context": "Bass sound",
      "parameter_values": {
        "attack_time": 0.003,
        "filter_envelope_amount": 0.5,
        "amp_envelope_sustain": 0.3
      },
      "result": "Punchy bass with strong transient attack"
    }
  ],
  "created": "2026-04-02T21:15:00Z"
}

