{
  "id": "vst_technical_realtime-safety",
  "kb": "technical",
  "topic": "cpp-audio",
  "status": "harvested",
  "version": "1.0.0",
  "title": "Real-Time Audio Thread Safety",
  "summary": "Patterns and rules for safe audio thread execution without glitches or crashes",
  "description": "Real-time audio thread safety is the #1 failure mode in plugin development. The audio thread (processBlock) executes under strict timing constraints—typically every 1-10ms. Any operation with unbounded execution time causes audible glitches. The cardinal rules: NO allocations, NO mutex locks, NO system calls, NO Objective-C/Swift in the RT path. All buffers must be pre-allocated in prepareToPlay(). All parameter access must use atomics or lock-free queues. The audio thread must complete its work within the buffer duration (e.g., 128 samples at 48kHz = 2.67ms).",
  "source": {
    "type": "expert-tutorial",
    "reference": "research/best-practices.md#audio-thread-safety",
    "url": "https://conference.audio.dev/llvms-real-time-safety-revolution-tools-for-modern-audio-development-adc-2024/"
  },
  "concepts": [
    {
      "name": "Real-time context",
      "description": "The audio callback thread with strict timing constraints"
    },
    {
      "name": "Priority inversion",
      "description": "When a high-priority audio thread waits on a low-priority thread holding a lock"
    },
    {
      "name": "Lock-free queue",
      "description": "SPSC (single-producer single-consumer) queue for thread-safe message passing"
    },
    {
      "name": "Pre-allocation",
      "description": "Allocating all memory before audio processing begins"
    }
  ],
  "code_blocks": [
    {
      "language": "cpp",
      "code": "// WRONG - allocation in processBlock\nvoid processBlock(AudioBuffer<float>& buffer, MidiBuffer&) {\n    std::vector<float> temp(buffer.getNumSamples()); // ALLOCATES!\n    // ...\n}\n\n// RIGHT - pre-allocated\nclass Processor {\n    std::vector<float> tempBuffer;\n    void prepareToPlay(double sr, int bs) {\n        tempBuffer.resize(bs); // Pre-allocate\n    }\n    void processBlock(AudioBuffer<float>& buffer, MidiBuffer&) {\n        // Use pre-allocated buffer\n    }\n};",
      "preserved": true,
      "description": "Wrong vs right pattern for buffer allocation"
    }
  ],
  "tags": ["realtime", "audio-thread", "safety", "allocation", "lock-free", "priority-inversion"],
  "related_topics": ["juce-framework", "testing"],
  "difficulty": "intermediate",
  "domain_relevance": 10,
