      "name": "AudioProcessorValueTreeState",
      "description": "JUCE class for thread-safe parameter management"
    },
    {
      "name": "ParameterLayout",
      "description": "Builder pattern for defining parameters at construction"
    },
    {
      "name": "SliderAttachment",
      "description": "Automatic binding between slider UI and parameter"
    },
    {
      "name": "Atomic parameter access",
      "description": "Lock-free parameter reads using std::atomic<float>*"
    }
  ],
  "code_blocks": [
    {
      "language": "cpp",
      "code": "class PluginProcessor : public juce::AudioProcessor {\npublic:\n    PluginProcessor()\n        : apvts(*this, nullptr, \"Parameters\", createParameterLayout())\n    {\n        // Cache parameter pointers for RT access\n        gainParam = apvts.getRawParameterValue(\"gain\");\n    }\n    \n    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override {\n        float gain = gainParam->load();  // Thread-safe atomic\n        buffer.applyGain(gain);\n    }\nprivate:\n    juce::AudioProcessorValueTreeState apvts;\n    std::atomic<float>* gainParam;\n};",
