        "title": "[Architect] — Define parameter list",
        "description": "Complete parameter list with min/max/default, automatable flag",
        "output": "SPEC.md (parameters section)"
      },
      {
        "title": "[Coordinator] — Phase gate",
        "description": "Verify all creative decisions documented and human approved",
        "gate_conditions": [
          "Sound identity words defined (not paraphrased)",
          "Signal flow diagram exists",
          "Parameter list complete with ranges",
          "Target genre/use case defined",
          "Human approval recorded"
        ]
      }
    ]
  },
  {
    "title": "Phase 1: Performance Baseline",
    "purpose": "Establish performance context before changes (optional)",
