  {
    "title": "Phase 2: Architecture",
    "purpose": "Design signal flow and module structure before implementation",
    "human_approval": true,
    "compilation": {
      "context_load": ["KB:technical", "KB:sound-design"],
      "role_mindset": "Architect — designing structure",
      "objective": "Design module structure, signal flow, state management",
