        "title": "[Architect] — Define parameter routing",
        "description": "Map parameters to modules, define modulation routing",
        "output": "architecture/parameters.md"
      },
      {
        "title": "[Architect] — Define state management",
        "description": "Preset format, automation support, save/load approach",
        "output": "architecture/state-management.md"
      },
      {
        "title": "[Stakeholder] — Approve architecture",
        "description": "Human reviews and approves signal flow and architecture",
        "output": "decisions-ledger.md (approval entry)"
      },
      {
        "title": "[Coordinator] — Phase gate",
        "description": "Verify architecture complete and approved",
        "gate_conditions": [
          "Module diagram exists",
          "Parameter routing defined",
          "State management approach defined",
          "Test strategy documented",
          "Human approval recorded"
        ]
      }
    ]
  },
  {
    "title": "Phase 3: Project Setup",
    "purpose": "Create build system, tests, project structure",
