        "description": "CMake with FetchContent for JUCE",
        "output": "CMakeLists.txt"
      },
      {
        "title": "[Builder] — Create directory structure",
        "description": "src/, tests/, docs/ directories",
        "output": "Directory structure"
      },
      {
        "title": "[Builder] — Configure test framework",
        "description": "Catch2 or GoogleTest",
        "output": "tests/CMakeLists.txt"
      },
      {
        "title": "[Builder] — Verify clean build",
        "description": "Build succeeds, tests run",
        "output": "Build verification"
      },
      {
        "title": "[Coordinator] — Phase gate",
        "description": "Verify project builds and tests run",
        "gate_conditions": [
          "CMakeLists.txt exists and builds",
          "Test framework configured",
          "Directory structure matches architecture",
          "Clean build passes"
        ]
      }
    ]
  },
