        "output": "src/Envelope.h, src/Envelope.cpp"
      },
      {
        "title": "[Builder] — Implement LFO",
        "description": "LFO for modulation with rate, depth, waveform",
        "output": "src/LFO.h, src/LFO.cpp"
      },
      {
        "title": "[Builder] — Implement effects",
        "description": "Effects (reverb, delay, etc.) as defined in architecture",
        "output": "src/Effects.h, src/Effects.cpp"
      },
      {
        "title": "[Builder] — Integrate in Processor",
        "description": "Connect all modules in PluginProcessor",
        "output": "src/PluginProcessor.cpp"
      },
      {
        "title": "[Auditor] — Audio thread safety audit",
        "description": "Verify no allocations, locks, or system calls in processBlock",
        "output": "docs/audio-thread-audit.md"
      },
      {
        "title": "[Coordinator] — Phase gate",
        "description": "Verify DSP implementation complete and thread-safe",
        "gate_conditions": [
          "All modules implemented",
          "Unit tests pass",
          "Audio thread safety audit passed",
          "Basic audio output verified"
        ]
      }
    ]
  },
  {
    "title": "Phase 5: State Management",
    "purpose": "Implement APVTS, presets, state serialization",
    "human_approval": false,
    "compilation": {
      "context_load": ["src/", "architecture/parameters.md"],
