      },
      {
        "title": "[Builder] — Connect parameters to modules",
        "description": "Parameter attachments to module setters",
        "output": "Updated src/PluginProcessor.cpp"
      },
      {
        "title": "[Builder] — Implement preset system",
        "description": "getStateInformation, setStateInformation",
        "output": "Preset save/load functionality"
      },
      {
        "title": "[Auditor] — Verify parameter smoothing",
