{
  "title": "VST Product Lifecycle Playbook",
  "version": 1,
  "description": "13-phase playbook for VST plugin development from specification through commercial release. Designed for single developer using AI assistance. Covers DSP implementation, state management, GUI, validation, DAW testing, licensing, and marketplace launch.",
  "phase_summary": [
    "Phase 0: Specification — Define what to build before how",
    "Phase 1: Performance Baseline — Establish performance context (optional)",
    "Phase 2: Architecture — Design signal flow and module structure",
    "Phase 3: Project Setup — Create build system, tests, structure",
    "Phase 4: DSP Implementation — Core audio processing",
    "Phase 5: State Management — Parameters, presets, state serialization",
    "Phase 6: Integration — Connect modules, verify plugin loads",
    "Phase 7: GUI Design — Visual interface, controls, accessibility",
    "Phase 8: Validation — Unit tests, thread safety, gain staging",
    "Phase 9: DAW Testing — Human perceptual testing",
    "Phase 10: Licensing — Integrate copy protection",
    "Phase 11: Marketplace Prep — Product page, screenshots, demos",
    "Phase 12: Marketing — Pre-launch audience, launch strategy"
  ],
  "workflow_model": "role-based-single-agent",
  "defaults": {
    "model": "opus",
    "context_budget_tokens": 64000,
    "system_prompt_budget": 2000,
    "temperature": 0.3
  },
  "knowledge_base": {
    "complexity": "bridged",
    "layers": [
      {
        "name": "technical",
        "domain_boundary": "C++ patterns, JUCE framework, DSP algorithms, audio thread safety, build systems",
